TRUSTED_AXIOMS = {a[0]:a for a in AXIOM_CATALOG}
import json
import pathlib
import time
import itertools
from collections import Counter

class ProofError(Exception):
    pass

class Kernel:
    def __init__(self,package):
        self.symbols=tuple(package['symbols'])
        self.variables=frozenset(package['variables'])
        self.records=package['records']
        self.bylabel={r['label']:i for i,r in enumerate(self.records)}
        if len(self.bylabel)!=len(self.records) or len(self.symbols)!=len(set(self.symbols)):
            raise ProofError('duplicate')
        self.verified=set()
        self.steps=0
        self.saved=0
        self.applications=0
        self.expr=[tuple(r['expr']) for r in self.records]
        self.varsets=[frozenset(self.variables.intersection(e)) for e in self.expr]
        self.validate()
    def validate(self):
        for i,r in enumerate(self.records):
            if r['kind'] not in ('f','e','a','p') or not self.expr[i] or self.expr[i][0] in self.variables or any(not 0<=s<len(self.symbols) for s in self.expr[i]):
                raise ProofError(('expression',r['label']))
            if r['kind']=='f':
                if len(self.expr[i])!=2 or self.expr[i][1] not in self.variables:
                    raise ProofError(('floating',r['label']))
            if r['kind']=='a':
                signature=[r['label'],r['expr'],[[self.records[h]['kind'],self.records[h]['expr']] for h in r['mand']],r['dv']]
                if TRUSTED_AXIOMS.get(r['label'])!=signature:
                    raise ProofError(('untrusted_axiom',r['label']))
            if r['kind'] in ('a','p'):
                mand=r['mand']
                if mand!=sorted(set(mand)) or any(h>=i or self.records[h]['kind'] not in ('f','e') for h in mand):
                    raise ProofError(('mandatory',r['label']))
                used=set(self.varsets[i])
                for h in mand:
                    if self.records[h]['kind']=='e':
                        used.update(self.varsets[h])
                typed=[self.expr[h][1] for h in mand if self.records[h]['kind']=='f']
                if len(typed)!=len(set(typed)) or set(typed)!=used:
                    raise ProofError(('mandatory_variables',r['label']))
                if any(len(d)!=2 or d[0]>=d[1] or not set(d)<=used for d in r['dv']):
                    raise ProofError(('mandatory_distinct',r['label']))
            if r['kind']=='p':
                ctx=r['ctx']
                if ctx!=sorted(set(ctx)) or any(h>=i or self.records[h]['kind'] not in ('f','e') for h in ctx):
                    raise ProofError(('context',r['label']))
                typed=[self.expr[h][1] for h in ctx if self.records[h]['kind']=='f']
                if len(typed)!=len(set(typed)):
                    raise ProofError(('context_types',r['label']))
                allused=set(self.varsets[i])
                for h in ctx:
                    if self.records[h]['kind']=='e':
                        allused.update(self.varsets[h])
                expected=[h for h in ctx if self.records[h]['kind']=='e' or self.expr[h][1] in allused]
                if expected!=r['mand'] or not allused<=set(typed):
                    raise ProofError(('context_mandatory',r['label']))
                dset=set()
                for d in r['ctxdv']:
                    if len(d)!=2 or d[0]>=d[1] or not set(d)<=set(typed):
                        raise ProofError(('context_distinct',r['label']))
                    dset.add(tuple(d))
                if {tuple(d) for d in r['dv']}!={d for d in dset if set(d)<=allused}:
                    raise ProofError(('context_distinct_mandatory',r['label']))
                refs,code=r['proof']
                if any(h>=i or h<0 or self.records[h]['kind'] in ('f','e') and h not in ctx for h in refs):
                    raise ProofError(('reference',r['label']))
                if code is not None and (not code or set(code)-set('ABCDEFGHIJKLMNOPQRSTUVWXYZ')):
                    raise ProofError(('compressed_characters',r['label']))
    def substitute(self,expr,sub):
        return tuple(s for token in expr for s in sub.get(token,(token,)))
    def verify_one(self,i):
        r=self.records[i]
        if r['kind']!='p':
            raise ProofError('not_theorem')
        stack=[]
        saved=[]
        ctx=set(r['ctx'])
        dvs={tuple(d) for d in r['ctxdv']}
        references,code=r['proof']
        def execute(h):
            self.steps+=1
            rule=self.records[h]
            if rule['kind'] in ('f','e'):
                if h not in ctx:
                    raise ProofError(('out_of_scope',r['label'],rule['label']))
                stack.append(self.expr[h])
                return
            if rule['kind']=='p' and h not in self.verified:
                raise ProofError(('unverified_dependency',r['label'],rule['label']))
            mand=rule['mand']
            count=len(mand)
            if len(stack)<count:
                raise ProofError(('underflow',r['label'],rule['label']))
            args=stack[len(stack)-count:] if count else []
            sub={}
            for hyp,arg in zip(mand,args):
                if self.records[hyp]['kind']=='f':
                    if not arg or arg[0]!=self.expr[hyp][0]:
                        raise ProofError(('type',r['label'],rule['label'],hyp))
                    sub[self.expr[hyp][1]]=arg[1:]
            for hyp,arg in zip(mand,args):
                if self.records[hyp]['kind']=='e' and self.substitute(self.expr[hyp],sub)!=arg:
                    raise ProofError(('essential',r['label'],rule['label'],self.records[hyp]['label']))
            for x,y in rule['dv']:
                sx=self.variables.intersection(sub[x])
                sy=self.variables.intersection(sub[y])
                if any(a==b or tuple(sorted((a,b))) not in dvs for a in sx for b in sy):
                    raise ProofError(('distinct',r['label'],rule['label'],self.symbols[x],self.symbols[y]))
            if count:
                del stack[-count:]
            stack.append(self.substitute(self.expr[h],sub))
            self.applications+=1
        if code is None:
            for h in references:
                execute(h)
        else:
            index=r['mand']+references
            n=0
            for letter in code:
                if 'U'<=letter<='Y':
                    n=5*n+ord(letter)-ord('U')+1
                elif 'A'<=letter<='T':
                    n=20*n+ord(letter)-ord('A')+1
                    if n<=len(index):
                        execute(index[n-1])
                    else:
                        position=n-len(index)-1
                        if not 0<=position<len(saved):
                            raise ProofError(('saved_index',r['label'],n))
                        stack.append(saved[position])
                        self.steps+=1
                    n=0
                elif letter=='Z':
                    if n or not stack:
                        raise ProofError(('save',r['label']))
                    saved.append(stack[-1])
                    self.saved+=1
                else:
                    raise ProofError(('code',r['label']))
            if n:
                raise ProofError(('unfinished_integer',r['label']))
        if stack!=[self.expr[i]]:
            raise ProofError(('conclusion',r['label'],len(stack)))
        self.verified.add(i)
    def verify_all(self):
        for i,r in enumerate(self.records):
            if r['kind']=='p':
                self.verify_one(i)
        return {'theorems':len(self.verified),'axioms':sum(r['kind']=='a' for r in self.records),'steps':self.steps,'saved':self.saved,'applications':self.applications}

from functools import lru_cache

class Syntax:
    def __init__(self,kernel):
        self.kernel=kernel
        self.symbol_id={s:i for i,s in enumerate(kernel.symbols)}
        self.types={}
        self.floats={}
        self.rules={}
        for i,r in enumerate(kernel.records):
            if r['kind']=='f':
                self.types[kernel.expr[i][1]]=kernel.expr[i][0]
                self.floats.setdefault(tuple(kernel.expr[i]),i)
            elif r['kind']=='a' and kernel.symbols[kernel.expr[i][0]]!='|-' and all(kernel.records[h]['kind']=='f' for h in r['mand']):
                self.rules.setdefault(kernel.expr[i][0],[]).append(i)
        self.memo={}
    def parse_ids(self,kind,expr):
        key=kind,tuple(expr)
        if key in self.memo:
            return self.memo[key]
        self.memo[key]=None
        if (kind,*expr) in self.floats:
            tree=(self.floats[(kind,*expr)],())
            self.memo[key]=tree
            return tree
        for label in self.rules.get(kind,[]):
            r=self.kernel.records[label]
            rhs=self.kernel.expr[label][1:]
            if len(rhs)>len(expr):
                continue
            mapping={self.kernel.expr[h][1]:self.kernel.expr[h][0] for h in r['mand']}
            if rhs and rhs[0] not in mapping and (not expr or rhs[0]!=expr[0]):
                continue
            if rhs and rhs[-1] not in mapping and (not expr or rhs[-1]!=expr[-1]):
                continue
            def match(i,j,sub,trees):
                if i==len(rhs):
                    return (sub,trees) if j==len(expr) else None
                if j>=len(expr):
                    return None
                token=rhs[i]
                if token not in mapping:
                    if token!=expr[j]:
                        return None
                    return match(i+1,j+1,sub,trees)
                if token in sub:
                    value=sub[token]
                    if tuple(expr[j:j+len(value)])!=value:
                        return None
                    return match(i+1,j+len(value),sub,trees)
                remaining=len(rhs)-i-1
                for end in range(j+1,len(expr)-remaining+1):
                    segment=tuple(expr[j:end])
                    tree=self.parse_ids(mapping[token],segment)
                    if tree is not None:
                        answer=match(i+1,end,sub|{token:segment},trees|{token:tree})
                        if answer is not None:
                            return answer
                return None
            answer=match(0,0,{}, {})
            if answer is not None:
                sub,trees=answer
                if any(set(sub[x])&self.kernel.variables & set(sub[y]) for x,y in r['dv']):
                    continue
                tree=(label,tuple(trees[self.kernel.expr[h][1]] for h in r['mand']))
                self.memo[key]=tree
                return tree
        return None
    def parse(self,kind,text):
        if isinstance(text,str):
            words=text.split()
        else:
            words=list(text)
        if any(x not in self.symbol_id for x in words):
            return None
        return self.parse_ids(self.symbol_id[kind],tuple(self.symbol_id[x] for x in words))

def theorem_view(kernel,label):
    i=kernel.bylabel[label]
    if i not in kernel.verified:
        raise ProofError(('not_verified',label))
    r=kernel.records[i]
    render=lambda expression:' '.join(kernel.symbols[x] for x in expression)
    return {'label':label,'statement':render(kernel.expr[i]),'mandatory_hypotheses':[(kernel.records[h]['kind'],kernel.records[h]['label'],render(kernel.expr[h])) for h in r['mand']], 'distinct_variables':[(kernel.symbols[x],kernel.symbols[y]) for x,y in r['dv']]}

def instantiate(kernel,label,substitution,disjoint):
    i=kernel.bylabel[label]
    if i not in kernel.verified:
        raise ProofError(('not_verified',label))
    r=kernel.records[i]
    if not hasattr(kernel,'syntax'):
        kernel.syntax=Syntax(kernel)
    syntax=kernel.syntax
    sub={}
    syntax_proofs={}
    expected={kernel.symbols[kernel.expr[h][1]] for h in r['mand'] if kernel.records[h]['kind']=='f'}
    if set(substitution)!=expected:
        raise ProofError(('substitution_domain',label,expected-set(substitution),set(substitution)-expected))
    for h in r['mand']:
        if kernel.records[h]['kind']=='f':
            kind,var=kernel.expr[h]
            text=substitution[kernel.symbols[var]]
            tree=syntax.parse(kernel.symbols[kind],text)
            if tree is None:
                raise ProofError(('substitution_type',label,kernel.symbols[var]))
            sub[var]=tuple(syntax.symbol_id[x] for x in text.split())
            syntax_proofs[kernel.symbols[var]]=tree
    context={tuple(sorted((syntax.symbol_id[x],syntax.symbol_id[y]))) for x,y in disjoint}
    if any(x==y or x not in kernel.variables or y not in kernel.variables for x,y in context):
        raise ProofError(('distinct_context',label))
    required=set()
    for x,y in r['dv']:
        xs=kernel.variables.intersection(sub[x])
        ys=kernel.variables.intersection(sub[y])
        for a in xs:
            for b in ys:
                if a==b or tuple(sorted((a,b))) not in context:
                    raise ProofError(('substitution_capture',label,kernel.symbols[a],kernel.symbols[b]))
                required.add(tuple(sorted((a,b))))
    render=lambda expression:' '.join(kernel.symbols[x] for x in expression)
    return {'statement':render(kernel.substitute(kernel.expr[i],sub)), 'essential_hypotheses':[render(kernel.substitute(kernel.expr[h],sub)) for h in r['mand'] if kernel.records[h]['kind']=='e'], 'distinct_variables':sorted((kernel.symbols[x],kernel.symbols[y]) for x,y in required), 'syntax_proofs':syntax_proofs,'source':label}

_DATABASE = None
_DATABASE_REPORT = None

def load_package():
    return json.loads(gzip.decompress(base64.b64decode(PACKAGE_GZIP_BASE64)))

def verify_database():
    global _DATABASE, _DATABASE_REPORT
    if _DATABASE is None:
        kernel = Kernel(load_package())
        report = kernel.verify_all()
        _DATABASE = kernel
        _DATABASE_REPORT = report
    return _DATABASE

def verified_theorem(label):
    return theorem_view(verify_database(),label)

def instantiate_verified(label,substitution,disjoint):
    return instantiate(verify_database(),label,substitution,disjoint)

def apply_verified(label,substitution,premises,disjoint):
    instance=instantiate_verified(label,substitution,disjoint)
    if list(premises)!=instance['essential_hypotheses']:
        raise ProofError(('unproved_essential_hypotheses',label))
    return instance['statement']

def mutation_rejected(change):
    package=load_package()
    change(package)
    try:
        Kernel(package).verify_all()
    except (ProofError,KeyError,IndexError,ValueError,TypeError):
        return True
    return False

def record(package,label):
    return next(r for r in package['records'] if r['label']==label)

def database_checks():
    results=[]
    def check(identifier,condition):
        results.append({'id':identifier,'passed':bool(condition)})
    k=verify_database()
    package=load_package()
    check('all_dependency_proofs_to_explicit_axioms',len(k.verified)==sum(r['kind']=='p' for r in k.records))
    check('no_unproved_requested_root',all(k.bylabel[name] in k.verified for name in package['roots']))
    check('theorem_cannot_be_replaced_by_axiom',mutation_rejected(lambda p:record(p,'heicant').update(kind='a')))
    check('essential_axiom_hypothesis_cannot_be_deleted',mutation_rejected(lambda p:record(p,'ax-mp').update(mand=record(p,'ax-mp')['mand'][:-1])))
    check('incorrect_final_expression_rejected',mutation_rejected(lambda p:record(p,'heicant').update(expr=record(p,'cniccibl')['expr'])))
    check('compressed_unfinished_integer_rejected',mutation_rejected(lambda p:record(p,'id').update(proof=[[], 'UZ'])))
    check('compressed_future_saved_step_rejected',mutation_rejected(lambda p:record(p,'id').update(proof=[[], 'UYA'])))
    check('compressed_missing_premises_rejected',mutation_rejected(lambda p:record(p,'id').update(proof=[[], 'A'])))
    check('distinct_constraints_cannot_be_erased',mutation_rejected(lambda p:record(p,'heicant').update(ctxdv=[],dv=[])))
    return results

import itertools
from functools import lru_cache


def formula_parts(formula,operator):
    words=formula.removeprefix('|- ').split()
    if not words or words[0]!='(' or words[-1]!=')':
        return None
    depth=0
    cuts=[]
    for i,token in enumerate(words[1:-1],1):
        if token=='(':
            depth+=1
        elif token==')':
            depth-=1
        elif depth==0 and token==operator:
            cuts.append(i)
    if not cuts:
        return None
    return tuple(' '.join(words[a:b]) for a,b in zip([1]+[i+1 for i in cuts],cuts+[len(words)-1]))


def equality_parts(formula):
    words=formula.removeprefix('|- ').split()
    depth=0
    for i,token in enumerate(words):
        if token=='(':
            depth+=1
        elif token==')':
            depth-=1
        elif depth==0 and token=='=':
            return tuple(words[:i]),tuple(words[i+1:])
    raise ProofError(('not_equality',formula))



def syntax_free_bound(tree):
    kernel=verify_database()
    label,children=tree
    record=kernel.records[label]
    expression=kernel.expr[label]
    if record['kind']=='f':
        return ({kernel.symbols[expression[1]]},set()) if kernel.symbols[expression[0]]=='setvar' else (set(),set())
    parts=[syntax_free_bound(child) for child in children]
    byname={kernel.symbols[kernel.expr[h][1]]:part for h,part in zip(record['mand'],parts)}
    binders={'wal':(('x',),('ph',)), 'wex':(('x',),('ph',)), 'wral':(('x',),('ph',)), 'wrex':(('x',),('ph',)), 'cab':(('x',),('ph',)), 'crab':(('x',),('ph',)), 'cmpt':(('x',),('B',)), 'cmpo':(('x','y'),('C',)), 'csu':(('k',),('B',)), 'cprod':(('k',),('B',)), 'citg':(('x',),('B',))}
    free=set().union(*(p[0] for p in parts));bound=set().union(*(p[1] for p in parts))
    if record['label'] in binders:
        names,bodies=binders[record['label']]
        binding=set().union(*(byname[name][0] for name in names))
        free=set().union(*(p[0]-(binding if name in bodies else set()) for name,p in byname.items() if name not in names))
        bound|=binding
    elif record['label'] not in ('cv','weq','wcel'):
        bound.update(*(part[0] for h,part in zip(record['mand'],parts) if kernel.symbols[kernel.expr[h][0]]=='setvar'))
    return free,bound

def replace_term(formula,left,right):
    words=formula.split()
    kernel=verify_database()
    if not hasattr(kernel,'syntax'):
        kernel.syntax=Syntax(kernel)
    targets=[kernel.syntax.parse('class',list(term)) for term in (left,right)]
    target_formula=kernel.syntax.parse('wff',formula.removeprefix('|- '))
    if any(t is None for t in targets) or target_formula is None:
        raise ProofError('rewrite_syntax')
    free=set().union(*(syntax_free_bound(t)[0] for t in targets))
    bound=syntax_free_bound(target_formula)[1]
    if free&bound:
        raise ProofError(('capture_rewrite',formula,left,right))
    result=[]
    i=0
    count=0
    while i<len(words):
        if tuple(words[i:i+len(left)])==tuple(left):
            result.extend(right)
            i+=len(left)
            count+=1
        else:
            result.append(words[i])
            i+=1
    if not count:
        raise ProofError(('rewrite_not_found',formula,left))
    return ' '.join(result)


def syntax_expression(tree):
    kernel=verify_database();label,children=tree;r=kernel.records[label]
    if r['kind']=='f':return tuple(kernel.symbols[i] for i in kernel.expr[label][1:])
    mapping={kernel.expr[h][1]:syntax_expression(c) for h,c in zip(r['mand'],children)}
    return tuple(token for i in kernel.expr[label][1:] for token in mapping.get(i,(kernel.symbols[i],)))


def syntax_components(formula,label):
    kernel=verify_database()
    if not hasattr(kernel,'syntax'):kernel.syntax=Syntax(kernel)
    tree=kernel.syntax.parse('wff',formula.removeprefix('|- '))
    if tree is None or kernel.records[tree[0]]['label']!=label:
        raise ProofError(('logical_syntax',formula,label))
    r=kernel.records[tree[0]]
    return {kernel.symbols[kernel.expr[h][1]]:' '.join(syntax_expression(c)) for h,c in zip(r['mand'],tree[1])}


def bound_instance(body,variable,term):
    kernel=verify_database()
    if not hasattr(kernel,'syntax'):kernel.syntax=Syntax(kernel)
    tree=kernel.syntax.parse('wff',body)
    value=kernel.syntax.parse('class',term)
    if tree is None or value is None:raise ProofError('bound_substitution_syntax')
    free,bound=syntax_free_bound(tree)
    termfree=syntax_free_bound(value)[0]
    if variable in bound or termfree&bound:raise ProofError('bound_substitution_capture')
    result=' '.join(term if t==variable else t for t in body.split())
    if kernel.syntax.parse('wff',result) is None:raise ProofError('bound_substitution_result')
    return '|- '+result


@lru_cache(None)
def infer(proof):
    rule=proof[0]
    if rule=='assume':
        return proof[1],frozenset((proof[1],))
    if rule=='mm':
        _,label,sub,disjoint,children=proof
        premises=[infer(p) for p in children]
        result=apply_verified(label,dict(sub),[p[0] for p in premises],disjoint)
        return result,frozenset().union(*(p[1] for p in premises))
    if rule=='rall_elim':
        q,hq=infer(proof[1]);membership,hm=infer(proof[2])
        quant=syntax_components(q,'wral');mem=syntax_components(membership,'wcel')
        if quant['A']!=mem['B']:raise ProofError('restricted_universal_domain')
        return bound_instance(quant['ph'],quant['x'],mem['A']),hq|hm
    if rule=='and':
        ps=[infer(p) for p in proof[1:]]
        if len(ps) not in (2,3):
            raise ProofError('and_arity')
        return '|- ( '+' /\\ '.join(p[0].removeprefix('|- ') for p in ps)+' )',frozenset().union(*(p[1] for p in ps))
    if rule=='and_elim':
        p,h=infer(proof[1])
        parts=formula_parts(p,'/\\')
        if parts is None or not 0<=proof[2]<len(parts):
            raise ProofError('and_elimination')
        return '|- '+parts[proof[2]],h
    if rule=='mp':
        implication,hi=infer(proof[1])
        p,hp=infer(proof[2])
        parts=formula_parts(implication,'->')
        if parts is None or len(parts)!=2 or '|- '+parts[0]!=p:
            raise ProofError(('modus_ponens',implication,p))
        return '|- '+parts[1],hi|hp
    if rule=='imp_intro':
        result,h=infer(proof[2])
        assumption=proof[1]
        return '|- ( '+assumption.removeprefix('|- ')+' -> '+result.removeprefix('|- ')+' )',h-{assumption}
    if rule=='eqsym':
        p,h=infer(proof[1]);left,right=equality_parts(p)
        return '|- '+' '.join(right)+' = '+' '.join(left),h
    if rule=='rewrite':
        equality,he=infer(proof[1]);p,hp=infer(proof[2])
        left,right=equality_parts(equality)
        return replace_term(p,left,right),he|hp
    if rule=='iff_mp':
        biconditional,hb=infer(proof[1]);p,hp=infer(proof[2]);parts=formula_parts(biconditional,'<->')
        if parts is None or len(parts)!=2 or '|- '+parts[proof[3]]!=p:
            raise ProofError('biconditional_elimination')
        return '|- '+parts[1-proof[3]],hb|hp
    raise ProofError(('unknown_logical_rule',rule))


def mm(label,substitution=None,children=()):
    substitution={} if substitution is None else substitution
    view=verified_theorem(label)
    sub={h[2].split()[1]:h[2].split()[1] for h in view['mandatory_hypotheses'] if h[0]=='f'}
    if not set(substitution)<=set(sub):
        raise ProofError(('extra_substitution',label,set(substitution)-set(sub)))
    sub.update(substitution)
    db=verify_database()
    used=set(x for value in sub.values() for x in value.split() if x in {db.symbols[i] for i in db.variables})
    disjoint=tuple(itertools.combinations(sorted(used),2))
    result=('mm',label,tuple(sorted(sub.items())),disjoint,tuple(children))
    infer(result)
    return result


def assumption(formula):
    return ('assume',formula)


def both(*proofs):
    result=('and',*proofs);infer(result);return result


def mp(p,q):
    result=('mp',p,q);infer(result);return result


def lift(p):
    result=('imp_intro','|- T.',p);infer(result);return result


def unlift(p):
    return mp(p,mm('tru'))


def eqref(term):
    return mm('eqid',{'A':term})


def eqsym(p):
    result=('eqsym',p);infer(result);return result


def rewrite(e,p):
    result=('rewrite',e,p);infer(result);return result


def interval_uniform_certificate():
    x='( A [,] B )'
    full='( abs o. - )'
    c=f'( {full} |` ( {x} X. {x} ) )'
    d=f'( {full} |` ( CC X. CC ) )'
    jc=f'( MetOpen ` {c} )'
    jd=f'( MetOpen ` {d} )'
    j='( TopOpen ` CCfld )'
    rt='( topGen ` ran (,) )'
    tx=f'( {rt} |`t {x} )'
    fj=f'( {j} |`t {x} )'
    ha=assumption('|- A e. RR');hb=assumption('|- B e. RR');hlt=assumption('|- A < B')
    hf=assumption(f'|- F e. ( {x} -cn-> CC )')
    realpair=both(ha,hb)
    xrr=mp(mm('iccssre'),realpair)
    rrcc=mm('axresscn')
    xcc=mm('sstri',{'A':x,'B':'RR','C':'CC'},(xrr,rrcc))
    ccss=mm('ssid',{'A':'CC'})
    fm=mm('cnxmet')
    cm=mp(mm('xmetres2',{'D':full,'X':'CC','R':x}),both(fm,xcc))
    dm=mp(mm('xmetres2',{'D':full,'X':'CC','R':'CC'}),both(fm,ccss))
    compact=mp(mm('icccmp',{'A':'A','B':'B','J':rt,'T':tx},(eqref(rt),eqref(tx))),realpair)
    top_real=mp(mm('rerest',{'A':x,'J':j,'R':rt},(eqref(j),eqref(rt))),xrr)
    full_top=mm('cnfldtopn',{'J':j},(eqref(j),))
    top_metric=mp(mm('metrest',{'C':full,'D':c,'X':'CC','Y':x,'J':j,'K':jc},(eqref(c),full_top,eqref(jc))),both(fm,xcc))
    compact_metric=rewrite(top_metric,rewrite(eqsym(top_real),compact))
    continuity_space=mp(mm('cncfmet',{'A':x,'B':'CC','C':c,'D':d,'J':jc,'K':jd},(eqref(c),eqref(d),eqref(jc),eqref(jd))),both(xcc,ccss))
    topology_continuous=rewrite(continuity_space,hf)
    ha_xr=mp(mm('rexr',{'A':'A'}),ha);hb_xr=mp(mm('rexr',{'A':'B'}),hb)
    le=mp(mp(mm('ltle'),realpair),hlt)
    member=mp(mm('lbicc2'),both(ha_xr,hb_xr,le))
    xnonempty=mp(mm('ne0i',{'A':x,'B':'A'}),member)
    cnonempty=mp(mm('ne0i',{'A':'CC','B':'1'}),mm('ax1cn'))
    heine=unlift(mm('heicant',{'ph':'T.','C':c,'D':d,'X':x,'Y':'CC'},tuple(lift(p) for p in (cm,dm,compact_metric,xnonempty,cnonempty))))
    uniformly_continuous=rewrite(eqsym(heine),topology_continuous)
    cps=mp(mm('xmetpsmet',{'D':c,'X':x}),cm)
