    right_type=unlift(mm('itgrecl',{'ph':'T.','A':x,'B':'E'},(ereal,lift(eint))))
    trans=mp(mp(mm('letr',{'A':f'( abs ` {idiff} )','B':iabs,'C':ieta}),both(left_type,middle_type,right_type)),both(first,second))
    split=unlift(mm('itgsub',{'ph':'T.','A':x,'B':'Z','C':fx,'V':'CC'},(ztype,lift(zint),ftypepoint,lift(fint))))
