def substitute_tokens(text,mapping):
    return ' '.join(token2 for token in text.split() for token2 in mapping.get(token,token).split())


def instantiate_proof(proof,mapping):
    rule=proof[0]
    if rule=='assume':
        return assumption(substitute_tokens(proof[1],mapping))
    if rule=='mm':
        return mm(proof[1],{k:substitute_tokens(v,mapping) for k,v in proof[2]},tuple(instantiate_proof(p,mapping) for p in proof[4]))
    if rule=='rall_elim':
        result=('rall_elim',instantiate_proof(proof[1],mapping),instantiate_proof(proof[2],mapping));infer(result);return result
    if rule=='and':
        return both(*(instantiate_proof(p,mapping) for p in proof[1:]))
    if rule=='and_elim':
        return conjunct(instantiate_proof(proof[1],mapping),proof[2])
    if rule=='mp':
        return mp(instantiate_proof(proof[1],mapping),instantiate_proof(proof[2],mapping))
    if rule=='imp_intro':
        return implies(substitute_tokens(proof[1],mapping),instantiate_proof(proof[2],mapping))
    if rule=='eqsym':
        return eqsym(instantiate_proof(proof[1],mapping))
    if rule=='rewrite':
        return rewrite(instantiate_proof(proof[1],mapping),instantiate_proof(proof[2],mapping))
    if rule=='iff_mp':
        result=('iff_mp',instantiate_proof(proof[1],mapping),instantiate_proof(proof[2],mapping),proof[3]);infer(result);return result
    raise ProofError('substitution_rule')


def replace_assumptions(proof,replacements):
    if proof[0]=='assume':
        result=replacements.get(proof[1],proof)
        if infer(result)[0]!=proof[1]:
            raise ProofError('wrong_assumption_replacement')
        return result
    if proof[0]=='mm':
        return mm(proof[1],dict(proof[2]),tuple(replace_assumptions(p,replacements) for p in proof[4]))
    args=[]
    for p in proof[1:]:
        args.append(replace_assumptions(p,replacements) if isinstance(p,tuple) else p)
    result=(proof[0],*args);infer(result);return result


