import sympy as sp


def partition_property(value,end):
    return f'|- ( {value} e. CC /\\ ( abs ` ( {value} - S. ( A [,] {end} ) ( F ` x ) _d x ) ) <_ ( E x. ( {end} - A ) ) )'


def uniform_formula(e='E',r='R'):
    whole='( A [,] B )';metric=f'( ( abs o. - ) |` ( {whole} X. {whole} ) )';image='( ( abs o. - ) |` ( CC X. CC ) )'
    return f'|- A. x e. {whole} A. y e. {whole} ( ( x {metric} y ) < {r} -> ( ( F ` x ) {image} ( F ` y ) ) < {e} )'


def finite_partition_induction(base,step,definitions=None):
    definitions={'one':'( ( F ` U ) x. ( D - A ) )','append':'( S + ( ( F ` U ) x. ( D - C ) ) )'} if definitions is None else definitions
    common={'|- A e. RR','|- B e. RR','|- A <_ B','|- F e. ( ( A [,] B ) -cn-> CC )','|- E e. RR+','|- R e. RR+',uniform_formula()}
    base_h=common|{'|- D e. ( A [,] B )','|- U e. ( A [,] D )','|- ( D - A ) < R'}
    step_h=common|{'|- C e. ( A [,] B )','|- D e. ( A [,] B )','|- C <_ D','|- U e. ( C [,] D )','|- ( D - C ) < R','|- S e. CC','|- ( abs ` ( S - S. ( A [,] C ) ( F ` x ) _d x ) ) <_ ( E x. ( C - A ) )'}
    if infer(base)!=(partition_property(definitions['one'],'D'),frozenset(base_h)):
        raise ProofError('partition_induction_base')
    if infer(step)!=(partition_property(definitions['append'],'D'),frozenset(step_h)):
        raise ProofError('partition_induction_step')
    if definitions['one']!='( ( F ` U ) x. ( D - A ) )' or definitions['append']!='( S + ( ( F ` U ) x. ( D - C ) ) )':
        raise ProofError('partition_recursive_sum_definition')
    return {'constructors':('one','append'),'definitions':definitions,'property':partition_property('S','C'),'hypotheses':frozenset(common),'endpoint_invariant':'|- C e. ( A [,] B )','base':base,'step':step}


def uniform_grid_certificate(node=None):
    a,l,n,j=sp.symbols('a l n j',real=True)
    node=(lambda k:a+k*l/n) if node is None else node
    w=l/n;b=a+l
    identities=(node(0)-a,node(n)-b,node(1)-a-w,node(j+1)-node(j)-w,node(j)-a-j*w,b-node(j)-(n-j)*w)
    if any(sp.cancel(e)!=0 for e in identities):raise ProofError('uniform_grid_recursion_or_endpoints')
    if sp.cancel(w-l/n)!=0:raise ProofError('uniform_grid_width')
    positive_natural=positive_natural_certificate()
    if positive_natural['formula']!='|- ( N e. RR+ /\\ 1 <_ N )' or positive_natural['hypotheses']!=frozenset({'|- N e. NN'}):raise ProofError('grid_positive_integer')
    length=interval_length_positive_certificate()
    if length['formula']!='|- ( B - A ) e. RR+' or length['hypotheses']!=frozenset({'|- A e. RR','|- B e. RR','|- A < B'}):raise ProofError('grid_positive_length')
    factors=((j*w,(j,w)),((n-j)*w,(n-j,w)),(w,(w,)))
    if any(sp.cancel(e-sp.prod(fs))!=0 for e,fs in factors):raise ProofError('grid_order_products')
    return {'node':'a+j*(b-a)/N','width':'(b-a)/N','index_domain':'N in NN; 0<=j<=N','nonnegative_factors':('j','N-j','(b-a)/N'),'first_constructor':'one','successor_constructor':'append','endpoints':('a','b'),'tags':'each tag is in its own closed cell','integer_proof':positive_natural['proof'],'length_proof':length['proof']}


def v(name):return ('var',name)
def fn(name,*args):return (name,*args)
def conj(*args):return ('and',*args)
def implies_f(a,b):return ('imp',a,b)
def forall(x,p):return ('all',x,p)
def exists(x,p):return ('ex',x,p)
def free_f(t):
    if not isinstance(t,tuple):return set()
    if t[0]=='var':return {t[1]}
    if t[0] in ('all','ex'):return free_f(t[2])-{t[1]}
    if t[0]=='sum':return free_f(t[2])|free_f(t[3])|(free_f(t[4])-{t[1]})
    return set().union(*(free_f(a) for a in t[1:]))
def sub_f(t,name,value):
    if not isinstance(t,tuple):return t
    if t[0]=='var':return value if t[1]==name else t
    if t[0]=='sum':
        if t[1] in free_f(value) and name!=t[1]:raise ProofError('sum_substitution_capture')
        return ('sum',t[1],sub_f(t[2],name,value),sub_f(t[3],name,value),t[4] if name==t[1] else sub_f(t[4],name,value))
    if t[0] in ('all','ex'):
        if t[1]==name:return t
        if t[1] in free_f(value):raise ProofError('formula_substitution_capture')
        return (t[0],t[1],sub_f(t[2],name,value))
    return (t[0],*(sub_f(a,name,value) for a in t[1:]))

A,B,F,E,R,Q,N,T,G,H=(v(n) for n in ('a','b','f','epsilon','delta','threshold','count','tags','g','h'))
L=fn('sub',B,A);ETA=fn('div',E,fn('mul',('number',2),L))
def positive(t):return fn('positive',t)
def natural(t):return fn('natural',t)
def continuous(f):return fn('continuous',f,A,B)
def uniform(f,e,d):return fn('uniform',f,A,B,e,d)
def tags(n,t):return fn('valid_tags',A,B,n,t)
def error(f,n,t):return fn('abs',fn('sub',fn('tagged_sum',f,A,B,n,t),fn('integral',f,A,B)))
GLOBALS=frozenset((fn('real',A),fn('real',B),fn('lt',A,B),continuous(F)))


def expect_raw(result,formula,hypotheses):
    if result['formula']!=formula or result['hypotheses']!=frozenset(hypotheses):raise ProofError('bridge_lemma_scope')
    return result


def bridge_lemma(name):
    if name=='length':
        r=expect_raw(interval_length_positive_certificate(),'|- ( B - A ) e. RR+',{'|- A e. RR','|- B e. RR','|- A < B'})
        return positive(L),frozenset((fn('real',A),fn('real',B),fn('lt',A,B)))
    if name=='budget':
        expect_raw(epsilon_budget_certificate(),'|- ( E / ( 2 x. L ) ) e. RR+',{'|- E e. RR+','|- L e. RR+'})
        return positive(ETA),frozenset((positive(E),positive(L)))
    if name=='uniform_witness':
        r=uniform_witness_certificate()
        expected='|- E. c e. RR+ '+uniform_formula('( E / ( 2 x. L ) )','c').removeprefix('|- ')
        expect_raw(r,expected,{'|- A e. RR','|- B e. RR','|- A < B','|- F e. ( ( A [,] B ) -cn-> CC )','|- E e. RR+','|- L e. RR+'})
        return exists('w_delta',conj(positive(v('w_delta')),uniform(F,ETA,v('w_delta')))),GLOBALS|{positive(E),positive(L)}
    if name=='archimedes':
        expect_raw(archimedean_mesh_certificate(),'|- E. n e. NN ( L / D ) < n',{'|- L e. RR+','|- D e. RR+'})
        return exists('w_threshold',conj(natural(v('w_threshold')),fn('lt',fn('div',L,R),v('w_threshold')))),frozenset((positive(L),positive(R)))
    if name=='mesh':
        expect_raw(eventual_mesh_certificate(),'|- ( L / N ) < D',{'|- L e. RR+','|- D e. RR+','|- N e. NN','|- Q e. NN','|- ( L / D ) < Q','|- Q <_ N'})
        return fn('lt',fn('div',L,N),R),frozenset((positive(L),positive(R),natural(N),natural(Q),fn('lt',fn('div',L,R),Q),fn('le',Q,N)))
    if name=='finite_grid_bound':
        induction=finite_partition_induction(tagged_base_error_certificate()['proof'],tagged_append_error_certificate()['proof'])
        grid=uniform_grid_certificate()
        expect_raw(interval_order_certificate(),'|- A <_ B',{'|- A e. RR','|- B e. RR','|- A < B'})
        if induction['endpoint_invariant']!='|- C e. ( A [,] B )' or grid['endpoints']!=('a','b'):raise ProofError('grid_induction_endpoint')
        if induction['hypotheses']!=frozenset({'|- A e. RR','|- B e. RR','|- A <_ B','|- F e. ( ( A [,] B ) -cn-> CC )','|- E e. RR+','|- R e. RR+',uniform_formula()}):raise ProofError('finite_grid_scope')
        expect_raw(whole_integral_type_certificate(),'|- S. ( A [,] B ) ( F ` x ) _d x e. CC',{'|- A e. RR','|- B e. RR','|- F e. ( ( A [,] B ) -cn-> CC )'})
        return conj(fn('complex',fn('tagged_sum',F,A,B,N,T)),fn('complex',fn('integral',F,A,B)),fn('le',error(F,N,T),fn('mul',ETA,L))),GLOBALS|{positive(ETA),positive(R),uniform(F,ETA,R),natural(N),tags(N,T),fn('lt',fn('div',L,N),R)}
    if name=='budget_strict':
        expect_raw(epsilon_final_bound_certificate(),'|- ( ( E / ( 2 x. L ) ) x. L ) < E',{'|- E e. RR+','|- L e. RR+'})
        return fn('lt',fn('mul',ETA,L),E),frozenset((positive(E),positive(L)))
    if name=='error_real':
        expect_raw(absolute_error_real_certificate(),'|- ( abs ` ( S - J ) ) e. RR',{'|- S e. CC','|- J e. CC'})
        return fn('real',error(F,N,T)),frozenset((fn('complex',fn('tagged_sum',F,A,B,N,T)),fn('complex',fn('integral',F,A,B))))
    if name=='budget_real':
        expect_raw(budget_real_certificate(),'|- ( ( ( E / ( 2 x. L ) ) x. L ) e. RR /\\ E e. RR )',{'|- E e. RR+','|- L e. RR+'})
        return conj(fn('real',fn('mul',ETA,L)),fn('real',E)),frozenset((positive(E),positive(L)))
    if name=='right_tags':
        uniform_grid_certificate()
        expect_raw(cell_right_endpoint_certificate(),'|- D e. ( C [,] D )',{'|- C e. RR','|- D e. RR','|- C <_ D'})
        return tags(N,right_tags()),GLOBALS|{natural(N)}
    if name=='right_sum_identity':
        finite_sum_identity_certificate('right')
        return fn('eq',fn('tagged_sum',F,A,B,N,right_tags()),right_sum()),GLOBALS|{natural(N)}
    if name=='weighted_sum_identity':
        finite_sum_identity_certificate('weighted')
        return fn('eq',fn('tagged_sum',fn('pointwise_product',G,H),A,B,N,T),weighted_sum()),(GLOBALS-{continuous(F)})|{continuous(G),continuous(H),natural(N),tags(N,T)}
    if name=='duration_width':
        expect_raw(positive_sub_zero_certificate(),'|- ( T - 0 ) = T',{'|- T e. RR+'})
        return fn('eq',fn('sub',v('duration'),('number',0)),v('duration')),frozenset((positive(v('duration')),))
    if name=='zero_interval':
        expect_raw(positive_zero_interval_certificate(),'|- ( 0 e. RR /\\ T e. RR /\\ 0 < T )',{'|- T e. RR+'})
        return conj(fn('real',('number',0)),fn('real',v('duration')),fn('lt',('number',0),v('duration'))),frozenset((positive(v('duration')),))
    if name=='product':
        r=weighted_continuity_certificate();whole='( A [,] B )'
        expect_raw(r,f'|- ( z e. {whole} |-> ( ( G ` z ) x. ( F ` z ) ) ) e. ( {whole} -cn-> CC )',{'|- F e. ( ( A [,] B ) -cn-> CC )','|- G e. ( ( A [,] B ) -cn-> CC )'})
        return continuous(fn('pointwise_product',G,H)),frozenset((continuous(G),continuous(H)))
    raise ProofError(('unknown_analytic_bridge',name))


@lru_cache(None)
def analytic_infer(proof):
    rule=proof[0]
    if rule=='hyp':return proof[1],frozenset((proof[1],))
    if rule=='lemma':
        conclusion,required=bridge_lemma(proof[1]);children=[analytic_infer(p) for p in proof[2]]
        if {p[0] for p in children}!=set(required):raise ProofError(('analytic_lemma_premises',proof[1]))
        return conclusion,frozenset().union(*(p[1] for p in children))
    if rule=='and':
        ps=[analytic_infer(p) for p in proof[1:]]
        return conj(*(p[0] for p in ps)),frozenset().union(*(p[1] for p in ps))
    if rule=='get':
        f,h=analytic_infer(proof[1])
        if f[0]!='and' or not 0<=proof[2]<len(f)-1:raise ProofError('analytic_and_elimination')
        return f[proof[2]+1],h
    if rule=='imp':
        f,h=analytic_infer(proof[2]);return implies_f(proof[1],f),h-{proof[1]}
    if rule=='mp':
        f,h=analytic_infer(proof[1]);g,k=analytic_infer(proof[2])
        if f[0]!='imp' or f[1]!=g:raise ProofError('analytic_modus_ponens')
        return f[2],h|k
    if rule=='all':
        f,h=analytic_infer(proof[2])
        if any(proof[1] in free_f(q) for q in h):raise ProofError('analytic_universal_freshness')
        return forall(proof[1],f),h
    if rule=='instantiate':
        f,h=analytic_infer(proof[1])
        if f[0]!='all':raise ProofError('analytic_universal_elimination')
        return sub_f(f[2],f[1],proof[2]),h
    if rule=='exists':
        _,name,body,witness,child=proof;f,h=analytic_infer(child)
        if f!=sub_f(body,name,witness):raise ProofError('analytic_existential_introduction')
        return exists(name,body),h
    if rule=='choose':
        existence,he=analytic_infer(proof[1]);result,hb=analytic_infer(proof[3]);fresh=proof[2]
        if existence[0]!='ex':raise ProofError('analytic_existential_elimination')
        instance=sub_f(existence[2],existence[1],v(fresh));remaining=hb-{instance}
        if fresh in free_f(result) or any(fresh in free_f(p) for p in he|remaining):raise ProofError('analytic_existential_escape')
        return result,he|remaining
    if rule=='rewrite':
        equation,he=analytic_infer(proof[1]);f,h=analytic_infer(proof[2])
        if equation[0]!='eq':raise ProofError('analytic_rewrite_equality')
        return replace_f(f,equation[1],equation[2]),he|h
    if rule=='le_lt':
        judgments=[analytic_infer(p) for p in proof[1:]]
        if len(judgments)!=5:raise ProofError('analytic_order_arity')
        first,second=judgments[0][0],judgments[1][0]
        if first[0]!='le' or second[0]!='lt' or first[2]!=second[1]:raise ProofError('analytic_order_transitivity')
        if [p[0] for p in judgments[2:]]!=[fn('real',t) for t in (first[1],first[2],second[2])]:raise ProofError('analytic_order_real_premises')
        view=verified_theorem('lelttr')
        if view['statement']!='|- ( ( A e. RR /\\ B e. RR /\\ C e. RR ) -> ( ( A <_ B /\\ B < C ) -> A < C ) )':raise ProofError('real_order_rule')
        return fn('lt',first[1],second[2]),frozenset().union(*(p[1] for p in judgments))
    raise ProofError(('analytic_rule',rule))


def analytic_lemma(name,facts):
    _,requirements=bridge_lemma(name);children=[]
    for requirement in sorted(requirements,key=repr):
        if requirement not in facts:raise ProofError(('missing_fact',name,requirement))
        children.append(facts[requirement])
    result=('lemma',name,tuple(children));analytic_infer(result);return result


def continuous_limit_certificate():
    facts={p:('hyp',p) for p in GLOBALS}
    length=analytic_lemma('length',facts);facts[positive(L)]=length
    facts[positive(E)]=('hyp',positive(E))
    budget=analytic_lemma('budget',facts);facts[positive(ETA)]=budget
    delta_exists=analytic_lemma('uniform_witness',facts)
    delta_body=conj(positive(R),uniform(F,ETA,R));delta_hyp=('hyp',delta_body)
    facts[positive(R)]=('get',delta_hyp,0);facts[uniform(F,ETA,R)]=('get',delta_hyp,1)
    threshold_exists=analytic_lemma('archimedes',facts)
    threshold_body=conj(natural(Q),fn('lt',fn('div',L,R),Q));threshold_hyp=('hyp',threshold_body)
    facts[natural(Q)]=('get',threshold_hyp,0);facts[fn('lt',fn('div',L,R),Q)]=('get',threshold_hyp,1)
    n_condition=conj(natural(N),fn('le',Q,N));n_hyp=('hyp',n_condition)
    facts[natural(N)]=('get',n_hyp,0);facts[fn('le',Q,N)]=('get',n_hyp,1)
    mesh=analytic_lemma('mesh',facts);facts[fn('lt',fn('div',L,N),R)]=mesh
    facts[tags(N,T)]=('hyp',tags(N,T))
    finite=analytic_lemma('finite_grid_bound',facts)
    finite_formula=analytic_infer(finite)[0]
    for index,component in enumerate(finite_formula[1:]):facts[component]=('get',finite,index)
    bound=('get',finite,2)
    error_real=analytic_lemma('error_real',facts)
    budget_real=analytic_lemma('budget_real',facts)
    strict_budget=analytic_lemma('budget_strict',facts)
    strict=('le_lt',bound,strict_budget,error_real,('get',budget_real,0),('get',budget_real,1))
    alltags=('all','tags',('imp',tags(N,T),strict))
    alln=('all','count',('imp',n_condition,alltags))
    witnessproof=('and',facts[natural(Q)],alln)
    witness_body=sub_f(analytic_infer(witnessproof)[0],'threshold',v('w_threshold_result'))
    existential=('exists','w_threshold_result',witness_body,Q,witnessproof)
    after_n=('choose',threshold_exists,'threshold',existential)
    after_delta=('choose',delta_exists,'delta',after_n)
    result=('all','epsilon',('imp',positive(E),after_delta))
    formula,hypotheses=analytic_infer(result)
    expected=forall('epsilon',implies_f(positive(E),exists('w_threshold_result',conj(natural(v('w_threshold_result')),forall('count',implies_f(conj(natural(N),fn('le',v('w_threshold_result'),N)),forall('tags',implies_f(tags(N,T),fn('lt',error(F,N,T),E)))))))))
    if formula!=expected or hypotheses!=GLOBALS:raise ProofError('continuous_limit_final_scope')
    return {'proof':result,'formula':formula,'hypotheses':hypotheses}


def weighted_limit_certificate():
    source=continuous_limit_certificate()['proof']
    universal=('all','f',('imp',continuous(F),source))
    product=fn('pointwise_product',G,H)
    instance=('instantiate',universal,product)
    assumptions={continuous(G):('hyp',continuous(G)),continuous(H):('hyp',continuous(H))}
    product_continuous=analytic_lemma('product',assumptions)
    result=('mp',instance,product_continuous)
    formula,hypotheses=analytic_infer(result)
    expected=sub_f(continuous_limit_certificate()['formula'],'f',product)
    expected_h=(GLOBALS-{continuous(F)})|{continuous(G),continuous(H)}
    if formula!=expected or hypotheses!=expected_h:raise ProofError('weighted_limit_final_scope')
    return {'proof':result,'formula':formula,'hypotheses':hypotheses}


def right_tags():return fn('right_tags',A,B,N)
def right_sum():
    width=fn('div',L,N);point=fn('add',A,fn('mul',v('j'),width))
    return ('sum','j',('number',1),N,fn('mul',fn('eval',F,point),width))
def weighted_sum():
    width=fn('div',L,N);point=fn('eval',T,v('j'))
    return ('sum','j',('number',1),N,fn('mul',fn('mul',fn('eval',G,point),fn('eval',H,point)),width))


def replace_f(formula,left,right):
    if formula==left:return right
    if not isinstance(formula,tuple):return formula
    if formula[0] in ('all','ex','sum') and formula[1] in free_f(left)|free_f(right):raise ProofError('analytic_rewrite_capture')
    return (formula[0],*(replace_f(a,left,right) for a in formula[1:]))


def finite_sum_identity_certificate(mode,base_coefficient=1,append_coefficient=1):
    uniform_grid_certificate()
    expect_raw(finite_sum_base_certificate(),'|- sum_ k e. ( 1 ... 1 ) ( H ` k ) = ( H ` 1 )',{'|- ( H ` 1 ) e. CC'})
    expect_raw(finite_sum_append_certificate(),'|- sum_ k e. ( 1 ... ( N + 1 ) ) ( H ` k ) = ( sum_ k e. ( 1 ... N ) ( H ` k ) + ( H ` ( N + 1 ) ) )',{'|- N e. NN','|- ( ( T. /\\ k e. ( 1 ... ( N + 1 ) ) ) -> ( H ` k ) e. CC )'})
    first,old,last=sp.symbols('first old last')
    if sp.expand(base_coefficient*first-first)!=0 or sp.expand(old+append_coefficient*last-(old+last))!=0:raise ProofError('finite_sum_translation_induction')
    if mode=='right':
        expect_raw(cell_right_endpoint_certificate(),'|- D e. ( C [,] D )',{'|- C e. RR','|- D e. RR','|- C <_ D'})
        summand=right_sum()[4]
        expected=fn('mul',fn('eval',F,fn('add',A,fn('mul',v('j'),fn('div',L,N)))),fn('div',L,N))
    elif mode=='weighted':
        expect_raw(weighted_value_certificate(),'|- ( ( z e. ( A [,] B ) |-> ( ( G ` z ) x. ( F ` z ) ) ) ` U ) = ( ( G ` U ) x. ( F ` U ) )',{'|- F e. ( ( A [,] B ) -cn-> CC )','|- G e. ( ( A [,] B ) -cn-> CC )','|- U e. ( A [,] B )'})
        summand=weighted_sum()[4]
        expected=fn('mul',fn('mul',fn('eval',G,fn('eval',T,v('j'))),fn('eval',H,fn('eval',T,v('j')))),fn('div',L,N))
    else:raise ProofError('finite_sum_translation_mode')
    if summand!=expected:raise ProofError('finite_sum_translation_summand')
    return {'mode':mode,'lower_index':1,'upper_index':N,'summand':summand,'base':'one_cell','step':'append_one_summand','proof_method':'structural_induction_using_verified_fsum_recursion'}


def displayed_sum_limit_certificate(weighted=False):
    source=weighted_limit_certificate() if weighted else continuous_limit_certificate()
    facts={h:('hyp',h) for h in source['hypotheses']}
    eps=('hyp',positive(E));facts[positive(E)]=eps
    existence=('mp',('instantiate',source['proof'],E),eps)
    exformula=analytic_infer(existence)[0]
    qbody=sub_f(exformula[2],exformula[1],Q);qhyp=('hyp',qbody)
    facts[natural(Q)]=('get',qhyp,0)
    n_condition=conj(natural(N),fn('le',Q,N));nhyp=('hyp',n_condition)
    facts[natural(N)]=('get',nhyp,0)
    alltags=('mp',('instantiate',('get',qhyp,1),N),nhyp)
    if weighted:
        thyp=('hyp',tags(N,T));facts[tags(N,T)]=thyp
        strict=('mp',('instantiate',alltags,T),thyp)
        identity=analytic_lemma('weighted_sum_identity',facts)
        strict=('rewrite',identity,strict)
        strict=('all','tags',('imp',tags(N,T),strict))
    else:
        valid=analytic_lemma('right_tags',facts)
        strict=('mp',('instantiate',alltags,right_tags()),valid)
        identity=analytic_lemma('right_sum_identity',facts)
        strict=('rewrite',identity,strict)
    alln=('all','count',('imp',n_condition,strict))
    witness=('and',facts[natural(Q)],alln)
    body=sub_f(analytic_infer(witness)[0],'threshold',v('convergence_threshold'))
    existential=('exists','convergence_threshold',body,Q,witness)
    chosen=('choose',existence,'threshold',existential)
    result=('all','epsilon',('imp',positive(E),chosen))
    formula,hypotheses=analytic_infer(result)
    if hypotheses!=source['hypotheses']:raise ProofError('displayed_sum_limit_scope')
    return {'proof':result,'formula':formula,'hypotheses':hypotheses}


def weighted_zero_interval_limit_certificate():
    source=displayed_sum_limit_certificate(True)
    hypotheses=sorted(source['hypotheses'],key=repr)
    proof=source['proof']
    for h in hypotheses:proof=('imp',h,proof)
    proof=('all','a',('all','b',proof))
    proof=('instantiate',('instantiate',proof,('number',0)),v('duration'))
    positive_duration=('hyp',positive(v('duration')))
    interval=analytic_lemma('zero_interval',{positive(v('duration')):positive_duration})
    interval_facts={component:('get',interval,i) for i,component in enumerate(analytic_infer(interval)[0][1:])}
    def specialized(f):return sub_f(sub_f(f,'a',('number',0)),'b',v('duration'))
    for h in reversed(hypotheses):
        newh=specialized(h);premise=interval_facts.get(newh,('hyp',newh))
        proof=('mp',proof,premise)
    width=analytic_lemma('duration_width',{positive(v('duration')):positive_duration})
    proof=('rewrite',width,proof)
    formula,assumptions=analytic_infer(proof)
    expected_h=frozenset((positive(v('duration')),specialized(continuous(G)),specialized(continuous(H))))
    expected_formula=replace_f(specialized(source['formula']),fn('sub',v('duration'),('number',0)),v('duration'))
    if formula!=expected_formula or assumptions!=expected_h:raise ProofError('weighted_zero_interval_scope')
    return {'proof':proof,'formula':formula,'hypotheses':assumptions,'fixed_curve':'h=f_n; n is fixed while count tends to infinity'}


def expected_riemann_formula(weighted=False):
    q=v('convergence_threshold');n_condition=conj(natural(N),fn('le',q,N))
    if weighted:
        integrand=fn('pointwise_product',G,H)
        strict=fn('lt',fn('abs',fn('sub',weighted_sum(),fn('integral',integrand,A,B))),E)
        core=forall('tags',implies_f(tags(N,T),strict))
    else:
        strict=fn('lt',fn('abs',fn('sub',right_sum(),fn('integral',F,A,B))),E)
        core=strict
    formula=forall('epsilon',implies_f(positive(E),exists('convergence_threshold',conj(natural(q),forall('count',implies_f(n_condition,core))))))
    if weighted:
        formula=sub_f(sub_f(formula,'a',('number',0)),'b',v('duration'))
        formula=replace_f(formula,fn('sub',v('duration'),('number',0)),v('duration'))
    return formula
def proof_rejected(operation):
    try:
        operation()
    except ProofError:
        return True
    return False


def find_proof_rule(proof,rule):
    if isinstance(proof,tuple):
        if proof and proof[0]==rule:return proof
        for child in proof:
            found=find_proof_rule(child,rule)
            if found is not None:return found
    return None


def riemann_checks():
    results=[]
    def check(identifier,condition):
        if not condition:raise AssertionError(identifier)
        results.append({'id':identifier,'passed':True})
    general=continuous_limit_certificate()
    weighted=weighted_limit_certificate()
    printed=displayed_sum_limit_certificate()
    weighted_printed=weighted_zero_interval_limit_certificate()
    check('continuous_tagged_riemann_limit',general['hypotheses']==GLOBALS and printed['hypotheses']==GLOBALS and printed['formula']==expected_riemann_formula())
    check('weighted_continuous_tagged_riemann_limit',weighted_printed['hypotheses']==frozenset((positive(v('duration')),fn('continuous',G,('number',0),v('duration')),fn('continuous',H,('number',0),v('duration')))) and weighted_printed['formula']==expected_riemann_formula(True) and weighted_printed['fixed_curve']=='h=f_n; n is fixed while count tends to infinity')
    check('right_endpoint_tags_and_one_to_N_sum',finite_sum_identity_certificate('right')['summand']==right_sum()[4] and finite_sum_identity_certificate('right')['lower_index']==1)
    check('weighted_zero_T_product_sum',finite_sum_identity_certificate('weighted')['summand']==weighted_sum()[4] and weighted_printed['formula']==analytic_infer(weighted_printed['proof'])[0])
    check('complex_integrands_include_signed_real_functions',weighted['hypotheses']==(GLOBALS-{continuous(F)})|{continuous(G),continuous(H)})
    check('finite_chain_induction_uses_integral_prefix',finite_partition_induction(tagged_base_error_certificate()['proof'],tagged_append_error_certificate()['proof'])['property']==partition_property('S','C'))
    check('all_subdivision_counts_are_positive_integers',eventual_mesh_certificate()['hypotheses']==frozenset({'|- L e. RR+','|- D e. RR+','|- N e. NN','|- Q e. NN','|- ( L / D ) < Q','|- Q <_ N'}))
    required=bridge_lemma('uniform_witness')[1]
    bad=('lemma','uniform_witness',tuple(('hyp',p) for p in required if p!=continuous(F)))
    check('continuity_premise_cannot_be_deleted',proof_rejected(lambda:analytic_infer(bad)))
    check('wrong_partition_append_rejected',proof_rejected(lambda:finite_partition_induction(tagged_base_error_certificate()['proof'],tagged_append_error_certificate()['proof'],{'one':'( ( F ` U ) x. ( D - A ) )','append':'( S + ( 2 x. ( ( F ` U ) x. ( D - C ) ) ) )'})))
    ga,gl,gn=sp.symbols('a l n',real=True)
    check('wrong_uniform_grid_rejected',proof_rejected(lambda:uniform_grid_certificate(lambda j:ga+2*j*gl/gn)))
    check('finite_sum_cannot_skip_first_term',proof_rejected(lambda:finite_sum_identity_certificate('right',0,1)))
    check('finite_sum_cannot_double_append',proof_rejected(lambda:finite_sum_identity_certificate('weighted',1,2)))
    check('universal_subdivision_variable_must_be_fresh',proof_rejected(lambda:analytic_infer(('all','count',('hyp',natural(N))))))
    existence=analytic_lemma('archimedes',{positive(L):('hyp',positive(L)),positive(R):('hyp',positive(R))})
    body=conj(natural(Q),fn('lt',fn('div',L,R),Q))
    check('existential_threshold_cannot_escape',proof_rejected(lambda:analytic_infer(('choose',existence,'threshold',('get',('hyp',body),0)))))
    order=find_proof_rule(general['proof'],'le_lt')
    check('real_order_guards_cannot_be_omitted',proof_rejected(lambda:analytic_infer(order[:3])))
    finite=find_proof_rule(general['proof'],'lemma')
    required=bridge_lemma('finite_grid_bound')[1]
    bad_tags=('lemma','finite_grid_bound',tuple(('hyp',p) for p in required if p!=tags(N,T)))
    check('arbitrary_points_outside_cells_not_accepted',proof_rejected(lambda:analytic_infer(bad_tags)))
    check('bound_variable_capture_rejected',proof_rejected(lambda:bound_instance('A. y x = y','x','y')))
    check('weighted_limit_has_no_finite_error_tolerance',weighted_printed['formula'][0]=='all' and weighted_printed['formula'][1]=='epsilon' and weighted_printed['formula'][2][0]=='imp' and weighted_printed['formula'][2][2][0]=='ex')
    return results

if __name__=='__main__':
    results=database_checks()+riemann_checks()
    report={'backend':'Python/independent-Metamath-and-natural-deduction-kernels','checks':len(results),'passed':all(r['passed'] for r in results),'formal_database':_DATABASE_REPORT,'scope':'Continuous complex-valued functions on a finite nondegenerate real interval; all positive integer uniform subdivisions and all within-cell tags. The ordinary formula uses right endpoints and indices 1..N. The weighted formula uses [0,T], T>0, with both continuous factors and a fixed curve index. The approximation is asymptotic, not a finite tolerance or rate.','results':results}
    print(json.dumps(report))
    raise SystemExit(0 if report['passed'] else 1)
